// TH14 v1.00b Stage 7 (Extra) MainSub04 D 组：4 对 ECir01，只实现 rank4 (!O)。
// 源入口 st07.ecl.txt:831-842；依赖 ECir01 94-127、ECir01_at 129-157。

const TIME_LIMIT: int = 2024;
const OPENING_BUFFER: int = 120;

// 源 426 moveBezierRel：mode8 三次 Hermite，切线针对归一化时间。
// 目标任务私有槽逐分量求值，每帧直接写位置（move_to dur=0 = 立即设）。
sub bezier(x0: fx, y0: fx, m0x: fx, m0y: fx, x1: fx, y1: fx, m1x: fx, m1y: fx, frames: int) {
    hermite_start(0, x0, x1, m0x, m1x, frames);
    hermite_start(1, y0, y1, m0y, m1y, frames);
    move_to(0, x0, y0, EASE_LINEAR);
    for i in 0..frames {
        wait(1);
        move_to(0, hermite_value(0), hermite_value(1), EASE_LINEAR);
    }
}

// 源 129-157 ECir01_at：32 轮，每 10 帧朝 B 与 B-π 各发一条 702 Line。
// 700 laserNew(0,0,128,0,14)：目标用飞棒生长近似；判定段取 0.8L、近端 0.1L，
// 宽度 14<32 -> 半高 14/4 -> 目标全宽 7。源 etSpeed 5 用于增长/平移速率。
async sub ecir_at(mirror: int) {
    // 源 0141：B = ANGLE_PLAYER - π/4 + 10°*RANDF2（RANDF2 在此取一次）
    var b: angle = aim_player() - 45deg + ((rand(3641) - 1820) as angle);
    for i in 0..32 {   // 源 0142/0152：D=32 轮
        // 源 0145-0146：etAngle(B); laserOn
        var h1: int = laser(3, $self_x, $self_y, b, 102.4fx, 7fx, 0, 9999, 0);
        lz_start(h1, 12.8fx);
        lz_speed(h1, 5fx, 102.4fx);
        // 源 0147-0148：etAngle(B - π); laserOn
        var h2: int = laser(3, $self_x, $self_y, b + 180deg, 102.4fx, 7fx, 0, 9999, 0);
        lz_start(h2, 12.8fx);
        lz_speed(h2, 5fx, 102.4fx);
        // 源 0149：B += A*(2π/18)，A=±1 -> ±20°
        b = b + ((mirror * 3641) as angle);
        wait(10);   // 源 0150
    }
    wait(60);   // 源 0153
}

// 源 94-127 ECir01：MF 子镜像初值 1 -> A=-1；F 子镜像初值 0 -> A=+1。
async sub ecir_main(mirror: int) {
    var a: fx = mirror as fx;
    set_invuln(65535);
    set_hurtbox(12fx);   // 源 setHurtbox(24,24) -> 半径 12
    set_hitbox(8fx);     // 源 setHitbox(16,16) -> 半径 8
    // 源 0108 与 0117 flagSet/flagClear(15)：其中 0x2 体碰位在本外壳的实际影响
    set_enemy_flag(ENEMY_NO_BODY, 1);

    // 源 0114 movePosRel(-192*A, 0)：父位于 (0,0)，出生即在 (-192*A, 0)
    // 源 0115-0116 moveBezierRel(120, 256A,-30, 160A,128, 0,0); wait(120)
    bezier(-192fx * a, 0fx, 256fx * a, -30fx, 160fx * a, 128fx, 0fx, 0fx, 120);

    set_enemy_flag(ENEMY_NO_BODY, 0);
    spawn ecir_at(mirror);   // 源 0120 @ECir01_at(%A) async

    // 源 0119 moveBezierRel(120, 0,0, -220A,192, -200A,-228)
    bezier(160fx * a, 128fx, 0fx, 0fx, -220fx * a, 192fx, -200fx * a, -228fx, 120);

    loop { wait(1); }   // 源 0122-0125 wait(1000) 循环保活
}

// 源 831-842 MainSub04 D 组：4 组；每组 MF 在组首、F 在 +90，组间隔 180，末 wait60。
async sub pattern() {
    wait(OPENING_BUFFER);
    for g in 0..4 {
        // 源 0834 enmCreateMF：子镜像初值 1 -> A=-1，站到 x=+192
        _ = spawn_enemy(192fx, 0fx, 160, 0, 0, 0, ecir_main(-1));
        wait(90);   // 源 0835
        // 源 0836 enmCreateF：子镜像初值 0 -> A=+1，站到 x=-192
        _ = spawn_enemy(-192fx, 0fx, 160, 0, 0, 0, ecir_main(1));
        wait(90);   // 源 0837
    }
    wait(60);   // 源 0840
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
